INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63992733', 63992733, 'analyze_legacy', 'Kota Semarang', 'kabkota', 'BADAN KEPEGAWAIAN, PENDIDIKAN DAN PELATIHAN', 'Belanja Modal Mebel (Meja Makan Custom )', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 75036000, 'January 2026', 'APBD', 1, 1, '10 Unit', 'Meja Makan Custom', 'Sesuai KAK', 75036000, 'high', 'Pengadaan meja makan custom untuk unit kerja kepegawaian, pendidikan, dan pelatihan terindikasi kurang relevan dengan fungsi utama layanan publik serta berpotensi merupakan belanja furnitur nonprioritas. Nilai anggaran juga cukup besar untuk 10 unit sehingga layak dikategorikan sebagai potensi pemborosan penuh sampai ada justifikasi kebutuhan yang kuat.', NULL, NULL, 3, 1, 1, 1, 1, 1242140);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63930510', 63930510, 'analyze_legacy', 'Kab. Nunukan', 'kabkota', 'BADAN PENANGGULANGAN BENCANA DAERAH', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Kertas dan Cover', 'Barang', 'E-Purchasing', 'Kalimantan Utara, Nunukan (Kab.)', 941600, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Kertas Cover; Kertas HVS folio 70 gr (Wil1);', '; ;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1242141);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63930382', 63930382, 'analyze_legacy', 'Kementerian Agama', 'central', 'IAIN PALANGKARAYA 426273', 'Cloud Siakad', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Tengah, Palangka Raya (Kota)', 271200000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Langganan Cloud Siakad selama 10 Bulan (01 Maret - 31 Desember 2026)', '1. Arsitektur Sistem - Sistem berbasis cloud computing (Software as a Service). - Dapat diakses melalui web browser tanpa instalasi lokal. - Mendukung multi user dengan akses bersamaan (concurrent access). - Infrastruktur memiliki kemampuan auto scaling. - Database dengan high availability dan redundansi. - Mendukung integrasi antar modul dalam satu platform terintegrasi. 2. Teknologi Platform - Aplikasi berbasis web (web-based application). - Mendukung pengembangan frontend modern (SPA framework atau setara). - Backend menggunakan arsitektur service-based atau modular. - Mendukung REST API atau Open API untuk integrasi dengan sistem lain. - Mendukung aplikasi mobile (Android dan/atau iOS). 3. Infrastruktur Cloud - Hosting pada cloud infrastructure dengan standar enterprise. - Multi-region deployment untuk redundansi layanan. - Sistem backup otomatis dan cold backup. - Monitoring performa sistem secara real-time. - SLA ketersediaan layanan tinggi (high availability). 4. Keamanan Sistem - Role Based Access Control (RBAC). - Web Application Firewall (WAF). - Enkripsi komunikasi data (HTTPS/SSL). - Audit log aktivitas pengguna. - Proses secure development lifecycle atau setara. - Backup data berkala dan disaster recovery plan. 5. Modul Fungsional Minimal A. Sistem Akademik: - Manajemen data mahasiswa dan dosen - KRS online - Jadwal perkuliahan - Presensi mahasiswa - Input dan manajemen nilai B. Penerimaan Mahasiswa Baru: - Portal pendaftaran online - Manajemen seleksi - Integrasi CBT (Computer Based Test) - Upload dokumen persyaratan C. Learning Management System: - Perkuliahan daring/hybrid - Dashboard aktivitas pembelajaran - Manajemen bahan ajar D. Sistem Keuangan: - Pembayaran UKT online - Monitoring tagihan mahasiswa - Manajemen beasiswa E. Sistem Mutu dan Pelaporan: - Dukungan pelaporan PDDIKTI - Dashboard monitoring indikator kinerja F. Sistem SDM: - Manajemen data pegawai dan dosen - Monitoring beban kerja dosen G. Alumni dan Career Center: - Tracer study - Portal informasi karir. 6. Integrasi Sistem - Mendukung integrasi dengan sistem eksternal melalui API. - Mendukung integrasi sistem nasional pendidikan tinggi. - Kemampuan ekspor dan impor data dalam format standar. 7. Implementasi dan Dukungan - Penyedia wajib melakukan setup awal sistem. - Migrasi data dari sistem lama. - Pelatihan pengguna (training). - Dokumentasi teknis dan user manual. - Dukungan teknis selama masa kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1242142);
