INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63932004', 63932004, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Perencanaan Teknis Pembangunan RS UPT Vertikal Riau - Lanjutan', 'Jasa Konsultansi', 'Dikecualikan', 'Riau, Pekanbaru (Kota)', 1149474000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Perencanaan Teknis Pembangunan RS UPT Vertikal Riau - Lanjutan merupakan lanjutan dari pekerjaan kontrak yang telah terlaksana dengan Persetujuan Kontrak Tahun Jamak sebelumnya Uraian pekerjaan meliputi pelaksanaan perencanaan teknis pembangunan RS UPT Vertikal Riau. Pekerjaan mencakup penyusunan dokumen perencanaan arsitektur, struktur, mekanikal, elektrikal, dan plumbing (MEP), prasarana pendukung, serta dokumen teknis lainnya yang diperlukan sebagai dasar pelaksanaan konstruksi. Kegiatan meliputi pengumpulan dan pengkajian data, penyusunan konsep desain, pengembangan desain, penyusunan gambar kerja dan spesifikasi teknis, perhitungan teknis, serta penyusunan Rencana Anggaran Biaya (RAB), sesuai standar teknis bangunan rumah sakit dan ketentuan peraturan perundang-undangan.', 'Spesifikasi pekerjaan berupa jasa konsultansi profesional untuk perencanaan teknis pembangunan RS UPT Vertikal Riau. Output pekerjaan berupa dokumen perencanaan teknis lengkap yang meliputi gambar rencana, spesifikasi teknis, perhitungan teknis, dan Rencana Anggaran Biaya (RAB). Pelaksanaan pekerjaan mengacu pada standar teknis bangunan rumah sakit, ketentuan peraturan perundang-undangan di bidang jasa konstruksi, serta persyaratan fungsi dan keselamatan fasilitas pelayanan kesehatan. Rincian metodologi, tahapan, dan spesifikasi teknis lebih lanjut ditetapkan dalam Kerangka Acuan Kerja (KAK) dan dokumen pemilihan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1243455);
